"""Support 'WHERE IN' SQL templates.  Replace the first occurence of the
    string '(?...?)' with some number of qmarks, e.g. '(?,?,?)'."""
def sql_replace_where_in(sql: Any, q_count: Any) -> object {
    qs = ','.join(('?' * q_count));
    sql2 = sql.replace('?...?', qs);
    return sql2;
}

