"""
    This function finds if the number is prime
    Returns:
        True if prime false otherwise
    """
def is_prime(number: int) -> object {
    for index in range(2, ((number // 2) + 1)) {
        if ((number % index) == 0) {
            return False;
        }
    }
    return True;
}

